@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');

:root {
  /* Brand Colors (OKLCH) */
  --color-primary: oklch(45% 0.15 260); /* Deep Indigo */
  --color-primary-hover: oklch(35% 0.13 260);
  --color-accent: oklch(85% 0.2 140); /* Energetic Green */
  --color-accent-hover: oklch(75% 0.2 140);

  /* Neutrals */
  --color-black: oklch(15% 0.02 260);
  --color-dark-gray: oklch(35% 0.01 260);
  --color-gray: oklch(70% 0.01 260);
  --color-light-gray: oklch(95% 0.01 260);
  --color-white: oklch(100% 0 0);

  /* Typography */
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;

  /* Layout */
  --max-width: 1200px;
  --radius-sm: 8px;
  --radius-md: 16px;
  --radius-lg: 24px;
  --radius-full: 9999px;

  /* Shadows */
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05);

  /* Transitions */
  --transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

/* Reset */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-sans);
  color: var(--color-black);
  background-color: var(--color-white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img {
  max-width: 100%;
  display: block;
}

a {
  text-decoration: none;
  color: inherit;
  transition: var(--transition);
}

button {
  cursor: pointer;
  font-family: inherit;
  border: none;
  background: none;
}

ul {
  list-style: none;
}

/* Typography Classes */
.h1 { font-size: clamp(2.5rem, 5vw, 4rem); font-weight: 800; line-height: 1.1; letter-spacing: -0.02em; }
.h2 { font-size: clamp(2rem, 4vw, 3rem); font-weight: 700; line-height: 1.2; letter-spacing: -0.01em; }
.h3 { font-size: clamp(1.5rem, 3vw, 2rem); font-weight: 700; line-height: 1.3; }
.h4 { font-size: 1.25rem; font-weight: 600; line-height: 1.4; }
.body-lg { font-size: clamp(1.125rem, 2vw, 1.25rem); color: var(--color-dark-gray); }

/* Layout Utilities */
.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 1.5rem;
}

.section { padding: 6rem 0; }
.section-light { background-color: var(--color-light-gray); }
.section-dark { background-color: var(--color-black); color: var(--color-white); }
.section-dark .body-lg, .section-dark p { color: oklch(85% 0.01 260); }

.grid { display: grid; gap: 2rem; }
.grid-2 { grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); }
.grid-3 { grid-template-columns: repeat(auto-fit, minmax(250px, 1fr)); }
.grid-4 { grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); }
.flex { display: flex; }
.flex-col { flex-direction: column; }
.items-center { align-items: center; }
.justify-center { justify-content: center; }
.justify-between { justify-content: space-between; }
.text-center { text-align: center; }
.gap-4 { gap: 1rem; }
.gap-8 { gap: 2rem; }
.mb-2 { margin-bottom: 0.5rem; }
.mb-4 { margin-bottom: 1rem; }
.mb-8 { margin-bottom: 2rem; }
.mb-12 { margin-bottom: 3rem; }
.mt-8 { margin-top: 2rem; }

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.875rem 1.75rem;
  border-radius: var(--radius-full);
  font-weight: 600;
  font-size: 1rem;
  transition: var(--transition);
  text-align: center;
}

.btn-primary {
  background-color: var(--color-primary);
  color: var(--color-white);
}
.btn-primary:hover {
  background-color: var(--color-primary-hover);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.btn-accent {
  background-color: var(--color-accent);
  color: var(--color-black);
}
.btn-accent:hover {
  background-color: var(--color-accent-hover);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.btn-outline {
  border: 2px solid var(--color-primary);
  color: var(--color-primary);
}
.btn-outline:hover {
  background-color: var(--color-primary);
  color: var(--color-white);
}

/* Navbar */
.navbar {
  position: sticky;
  top: 0;
  z-index: 100;
  background-color: rgba(255, 255, 255, 0.95);
  backdrop-filter: blur(8px);
  border-bottom: 1px solid var(--color-light-gray);
  padding: 1rem 0;
}
.nav-container {
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.logo {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--color-primary);
  letter-spacing: -0.02em;
}
.nav-links {
  display: flex;
  gap: 2rem;
  align-items: center;
}
.nav-link {
  font-weight: 500;
  color: var(--color-dark-gray);
}
.nav-link:hover, .nav-link.active {
  color: var(--color-primary);
}
.mobile-menu-btn {
  display: none;
  font-size: 1.5rem;
  color: var(--color-black);
}

/* Hero Section */
.hero {
  padding: 8rem 0 6rem;
  text-align: center;
  overflow: hidden;
}
.hero-content {
  max-width: 800px;
  margin: 0 auto;
}
.hero .btn-group {
  display: flex;
  gap: 1rem;
  justify-content: center;
  margin-top: 2.5rem;
}
.hero-visual {
  margin-top: 4rem;
  position: relative;
}
.hero-tabs {
  display: flex;
  justify-content: center;
  gap: 1rem;
  margin-bottom: 2rem;
}
.hero-tab-btn {
  padding: 0.75rem 1.5rem;
  border-radius: var(--radius-full);
  font-weight: 600;
  background-color: var(--color-light-gray);
  color: var(--color-dark-gray);
  transition: var(--transition);
}
.hero-tab-btn.active {
  background-color: var(--color-primary);
  color: var(--color-white);
}
.hero-preview {
  background: var(--color-light-gray);
  border-radius: var(--radius-lg);
  padding: 2rem;
  min-height: 400px;
  display: none;
  border: 1px solid oklch(90% 0.01 260);
  box-shadow: var(--shadow-lg);
  animation: fadeIn 0.4s ease-out forwards;
}
.hero-preview.active {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
}

/* Stats Bar */
.stats-bar {
  background-color: var(--color-primary);
  color: var(--color-white);
  padding: 3rem 0;
}
.stat-item h3 {
  font-size: clamp(2rem, 4vw, 3.5rem);
  font-weight: 800;
  color: var(--color-accent);
  margin-bottom: 0.5rem;
}
.stat-item p {
  font-size: 1.125rem;
  font-weight: 500;
}

/* Cards */
.card {
  background-color: var(--color-white);
  border-radius: var(--radius-md);
  padding: 2rem;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--color-light-gray);
  transition: var(--transition);
}
.card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-4px);
}
.card-icon {
  width: 48px;
  height: 48px;
  background-color: var(--color-primary);
  color: var(--color-white);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.5rem;
  font-weight: bold;
}

/* Tabs System (Why Choose Us) */
.tabs-container {
  display: grid;
  grid-template-columns: 300px 1fr;
  gap: 3rem;
  margin-top: 3rem;
}
.tab-list {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}
.tab-trigger {
  text-align: left;
  padding: 1rem 1.5rem;
  border-radius: var(--radius-md);
  font-weight: 600;
  color: var(--color-dark-gray);
  transition: var(--transition);
  border-left: 3px solid transparent;
}
.tab-trigger.active {
  background-color: var(--color-light-gray);
  color: var(--color-primary);
  border-left-color: var(--color-primary);
}
.tab-trigger:hover:not(.active) {
  background-color: oklch(98% 0 0);
}
.tab-panel {
  display: none;
  background-color: var(--color-white);
  padding: 2.5rem;
  border-radius: var(--radius-lg);
  border: 1px solid var(--color-light-gray);
  box-shadow: var(--shadow-sm);
  animation: fadeIn 0.4s ease-out forwards;
}
.tab-panel.active {
  display: block;
}
.tab-panel ul {
  margin-top: 1.5rem;
}
.tab-panel li {
  position: relative;
  padding-left: 1.5rem;
  margin-bottom: 1rem;
}
.tab-panel li::before {
  content: "→";
  position: absolute;
  left: 0;
  color: var(--color-primary);
  font-weight: bold;
}

/* Testimonials Carousel */
.carousel {
  position: relative;
  overflow: hidden;
  padding: 2rem 0;
}
.carousel-track {
  display: flex;
  transition: transform 0.5s ease-in-out;
}
.carousel-slide {
  min-width: 100%;
  padding: 0 1rem;
}
.testimonial-card {
  background-color: var(--color-white);
  border-radius: var(--radius-lg);
  padding: 3rem;
  box-shadow: var(--shadow-md);
  text-align: center;
  max-width: 800px;
  margin: 0 auto;
}
.testimonial-quote {
  font-size: clamp(1.25rem, 3vw, 1.75rem);
  font-weight: 500;
  color: var(--color-black);
  margin-bottom: 2rem;
  font-style: italic;
}
.testimonial-author {
  font-weight: 700;
  color: var(--color-primary);
}
.carousel-controls {
  display: flex;
  justify-content: center;
  gap: 1rem;
  margin-top: 2rem;
}
.carousel-btn {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background-color: var(--color-light-gray);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: var(--transition);
}
.carousel-btn:hover {
  background-color: var(--color-primary);
  color: var(--color-white);
}

/* Accordion (FAQ & Demo) */
.accordion {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  max-width: 800px;
  margin: 0 auto;
}
.accordion-item {
  border: 1px solid var(--color-light-gray);
  border-radius: var(--radius-md);
  overflow: hidden;
}
.accordion-header {
  width: 100%;
  text-align: left;
  padding: 1.5rem;
  background-color: var(--color-white);
  font-weight: 600;
  font-size: 1.125rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  transition: var(--transition);
}
.accordion-header:hover {
  background-color: var(--color-light-gray);
}
.accordion-icon {
  font-weight: bold;
  font-size: 1.25rem;
  transition: transform 0.3s ease;
  color: var(--color-primary);
}
.accordion-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease-out;
  background-color: var(--color-white);
}
.accordion-inner {
  padding: 0 1.5rem 1.5rem;
  color: var(--color-dark-gray);
}
.accordion-item.active .accordion-content {
  max-height: 500px; /* Arbitrary large value */
}
.accordion-item.active .accordion-icon {
  transform: rotate(45deg);
}

/* Integrations Grid */
.logo-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
  gap: 3rem;
  align-items: center;
  justify-items: center;
  opacity: 0.7;
}
.logo-item {
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--color-dark-gray);
  text-align: center;
}

/* Footer */
.footer {
  background-color: var(--color-black);
  color: var(--color-white);
  padding: 6rem 0 3rem;
}
.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
  gap: 3rem;
  margin-bottom: 4rem;
}
.footer-brand p {
  color: var(--color-gray);
  margin-top: 1rem;
}
.footer h4 {
  font-size: 1rem;
  margin-bottom: 1.5rem;
  color: var(--color-white);
}
.footer ul {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}
.footer a {
  color: var(--color-gray);
  font-size: 0.875rem;
}
.footer a:hover {
  color: var(--color-white);
}
.footer-bottom {
  padding-top: 2rem;
  border-top: 1px solid var(--color-dark-gray);
  display: flex;
  justify-content: space-between;
  color: var(--color-gray);
  font-size: 0.875rem;
}

/* Responsive */
@media (max-width: 992px) {
  .tabs-container {
    grid-template-columns: 1fr;
    gap: 2rem;
  }
  .tab-list {
    flex-direction: row;
    overflow-x: auto;
    padding-bottom: 1rem;
  }
  .tab-trigger {
    white-space: nowrap;
    border-left: none;
    border-bottom: 3px solid transparent;
  }
  .tab-trigger.active {
    border-left-color: transparent;
    border-bottom-color: var(--color-primary);
  }
  .footer-grid {
    grid-template-columns: 1fr 1fr;
  }
}

@media (max-width: 768px) {
  .nav-links {
    display: none;
  }
  .mobile-menu-btn {
    display: block;
  }
  .hero {
    padding: 6rem 0 4rem;
  }
  .hero .btn-group {
    flex-direction: column;
  }
  .footer-grid {
    grid-template-columns: 1fr;
  }
  .footer-bottom {
    flex-direction: column;
    gap: 1rem;
    text-align: center;
  }
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

document.addEventListener('DOMContentLoaded', () => {
  // Mobile Menu Toggle
  const mobileMenuBtn = document.querySelector('.mobile-menu-btn');
  const navLinks = document.querySelector('.nav-links');
  if (mobileMenuBtn && navLinks) {
    mobileMenuBtn.addEventListener('click', () => {
      navLinks.style.display = navLinks.style.display === 'flex' ? 'none' : 'flex';
      navLinks.style.flexDirection = 'column';
      navLinks.style.position = 'absolute';
      navLinks.style.top = '100%';
      navLinks.style.left = '0';
      navLinks.style.right = '0';
      navLinks.style.backgroundColor = 'rgba(255, 255, 255, 0.95)';
      navLinks.style.padding = '2rem';
      navLinks.style.boxShadow = 'var(--shadow-md)';
    });
  }

  // Hero Tab Switching (Homepage)
  const heroTabBtns = document.querySelectorAll('.hero-tab-btn');
  const heroPreviews = document.querySelectorAll('.hero-preview');

  if (heroTabBtns.length > 0 && heroPreviews.length > 0) {
    heroTabBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        const targetId = btn.getAttribute('data-target');

        // Remove active class from all
        heroTabBtns.forEach(b => b.classList.remove('active'));
        heroPreviews.forEach(p => p.classList.remove('active'));

        // Add active class to clicked
        btn.classList.add('active');
        document.getElementById(targetId).classList.add('active');
      });
    });
  }

  // Why Choose Us Tabs
  const tabTriggers = document.querySelectorAll('.tab-trigger');
  const tabPanels = document.querySelectorAll('.tab-panel');

  if (tabTriggers.length > 0 && tabPanels.length > 0) {
    tabTriggers.forEach(trigger => {
      trigger.addEventListener('click', () => {
        const targetId = trigger.getAttribute('data-target');

        tabTriggers.forEach(t => t.classList.remove('active'));
        tabPanels.forEach(p => p.classList.remove('active'));

        trigger.classList.add('active');
        document.getElementById(targetId).classList.add('active');
      });
    });
  }

  // Accordions (FAQ & Demo)
  const accordionHeaders = document.querySelectorAll('.accordion-header');

  if (accordionHeaders.length > 0) {
    accordionHeaders.forEach(header => {
      header.addEventListener('click', () => {
        const item = header.parentElement;
        const isActive = item.classList.contains('active');

        // Optional: close others
        const parent = item.closest('.accordion');
        if (parent) {
          parent.querySelectorAll('.accordion-item').forEach(i => i.classList.remove('active'));
        }

        if (!isActive) {
          item.classList.add('active');
        }
      });
    });
  }

  // Carousels (Testimonials)
  const carousels = document.querySelectorAll('.carousel');

  carousels.forEach(carousel => {
    const track = carousel.querySelector('.carousel-track');
    const slides = carousel.querySelectorAll('.carousel-slide');
    const prevBtn = carousel.querySelector('.carousel-prev');
    const nextBtn = carousel.querySelector('.carousel-next');

    if (!track || slides.length === 0 || !prevBtn || !nextBtn) return;

    let currentIndex = 0;

    const updateCarousel = () => {
      track.style.transform = `translateX(-${currentIndex * 100}%)`;
    };

    prevBtn.addEventListener('click', () => {
      currentIndex = (currentIndex > 0) ? currentIndex - 1 : slides.length - 1;
      updateCarousel();
    });

    nextBtn.addEventListener('click', () => {
      currentIndex = (currentIndex < slides.length - 1) ? currentIndex + 1 : 0;
      updateCarousel();
    });
  });
});
